import openai

# Initialize the OpenAI client
client = openai.OpenAI()

# Function to process multimodal input
def analyze_multimodal(image_path, text_query):
    with open(image_path, "rb") as image_file:
        response = client.chat.completions.create(
            model="gpt-4-vision-preview",
            messages=[
                {
                    "role": "user",
                    "content": [
                        {"type": "text", "text": text_query},
                        {"type": "image_url", "image_url": {"url": f"data:image/jpeg;base64,{base64.b64encode(image_file.read()).decode()}"}}
                    ]
                }
            ],
            max_tokens=500
        )
    return response.choices[0].message.content

# Example usage
result = analyze_multimodal("example.jpg", "Describe this image in detail")
print(result)
